        private final Map<FType, FValue> converted = new HashMap<FType, FValue>();

        Site(NumeralNumbers x, BigInteger signed) {
            this.digits = x.n.intValue();
            this.fractionDigits = x.m.intValue();
            this.radix = x.r.intValue();
            this.digitValue = x.v;
            this.radixPoint = x.radixPoint;
            this.kind = x.kind;
            this.signed = signed;
        }
    }

    static final class IntNumeral extends FInt implements Numeral {
        private final Site site;

        IntNumeral(int x, Site s) {
            super(x);
            site = s;
        }

        public Site site() {
            return site;
        }
    }

    static final class LongNumeral extends FLong implements Numeral {
        private final Site site;

        LongNumeral(long x, Site s) {
            super(x);
            site = s;
        }

        public Site site() {
            return site;
        }
    }

    static final class BigNumeral extends FBigNum implements Numeral {
        private final Site site;

        BigNumeral(BigInteger x, Site s) {
            super(x);
            site = s;
        }

        public Site site() {
            return site;
        }
    }

    static final class FloatNumeral extends FFloat implements Numeral {
        private final Site site;

        FloatNumeral(double x, Site s) {
            super(x);
            site = s;
        }

        public Site site() {
            return site;
        }
    }

    private static final Map<Object, Site> sites = new IdentityHashMap<Object, Site>();

    public static synchronized void reset() {
        sites.clear();
    }

    private static final BigInteger INT_MIN = BigInteger.valueOf(Integer.MIN_VALUE);
    private static final BigInteger INT_MAX = BigInteger.valueOf(Integer.MAX_VALUE);
    private static final BigInteger LONG_MIN = BigInteger.valueOf(Long.MIN_VALUE);
    private static final BigInteger LONG_MAX = BigInteger.valueOf(Long.MAX_VALUE);
    private static final BigInteger NN32_MAX = BigInteger.ONE.shiftLeft(32).subtract(BigInteger.ONE);
    private static final BigInteger NN64_MAX = BigInteger.ONE.shiftLeft(64).subtract(BigInteger.ONE);

    /** The digit part of a numeral's text, before its radix: digit-group separators and the radix point removed. */
    private static String digitPart(String text) {
        String s = text.replace("'", "").replace(" ", "");
        int under = s.indexOf('_');
        if (under >= 0) s = s.substring(0, under);
        return s.replace(".", "").replace("-", "");
    }

    private static int radixOf(String text) {
        int under = text.indexOf('_');
        if (under < 0) return 10;
        try {
            return Integer.parseInt(text.substring(under + 1).trim());
        }
        catch (NumberFormatException ex) {
            return 10;
        }
    }

    /** The value of the integer numeral x at its site. */
    public static FValue integer(IntLiteralExpr x) {
        synchronized (Numerals.class) {
            Site s = sites.get(x);
            if (s != null) return s.value;
            BigInteger v = x.getIntVal();
            s = new Site(NumeralNumbers.of(x), v);
            if (v.compareTo(INT_MIN) >= 0 && v.compareTo(INT_MAX) <= 0) {
                s.value = new IntNumeral(v.intValue(), s);
                s.plain = FInt.make(v.intValue());
            } else if (v.compareTo(LONG_MIN) >= 0 && v.compareTo(LONG_MAX) <= 0) {
                s.value = new LongNumeral(v.longValue(), s);
                s.plain = FLong.make(v.longValue());
            } else {
                s.value = new BigNumeral(v, s);
                s.plain = FBigNum.make(v);
            }
            sites.put(x, s);
            return s.value;
        }
    }

    /** The value of the numeral with a radix point x at its site. */
    public static FValue radixPoint(FloatLiteralExpr x) {
        synchronized (Numerals.class) {
            Site s = sites.get(x);
            if (s != null) return s.value;
            NumeralNumbers nn = NumeralNumbers.of(x);
            BigInteger v = nn.v;
            int r = nn.r.intValue();
            int m = nn.m.intValue();
            // The exact value as the node holds it, a negated numeral's magnitude negated.
            BigInteger den = BigInteger.valueOf(x.getDenomBase()).pow(x.getDenomPower());
            BigInteger num = x.getIntPart().multiply(den).add(x.getNumerator());
            if (nn.kind == NumeralNumbers.Kind.NEGATED) num = num.abs().negate();
            s = new Site(nn, num);
            s.denomBase = x.getDenomBase();
            s.denomPower = x.getDenomPower();
            double d = simpleDoubleArith.numeralToDouble(v, r, m);
            if (nn.kind == NumeralNumbers.Kind.NEGATED) d = -d;   // -0.0 keeps its sign
            s.value = new FloatNumeral(d, s);
            s.plain = FFloat.make(d);
            sites.put(x, s);
            return s.value;
        }
    }

    public static boolean isNumeral(FValue v) {
        return v instanceof Numeral;
    }

    /** Some argument is a numeral. */
    public static boolean anyNumeral(List<FValue> args) {
        for (FValue v : args) if (v instanceof Numeral) return true;
        return false;
    }

    /** v is a numeral, or a tuple that holds one. */
    public static boolean hasNumeral(FValue v) {
        if (v instanceof Numeral) return true;
        if (v instanceof FTuple) for (FValue e : ((FTuple) v).getVals()) if (hasNumeral(e)) return true;
        return false;
    }

    /** v without its numeral: a numeral's default alone, a tuple element by element. */
    public static FValue plain(FValue v) {
        if (v instanceof Numeral) return ((Numeral) v).site().plain;
        if (v instanceof FTuple) {
            if (!hasNumeral(v)) return v;
            return FTuple.make(plain(((FTuple) v).getVals()));
        }
        return v;
    }

    public static List<FValue> plain(List<FValue> args) {
        boolean any = false;
        for (FValue v : args) if (hasNumeral(v)) any = true;
        if (!any) return args;
        List<FValue> l = new ArrayList<FValue>(args.size());
        for (FValue v : args) l.add(plain(v));
        return l;
    }

    private static Environment library() {
        return Driver.getFortressLibrary();
    }

    private static FType libraryType(String name) {
        try {
            return library().getRootTypeNull(name);
        }
        catch (RuntimeException ex) {
            return null;
        }
    }

    /** NN32's type, which FortressBuiltin declares, so that FortressLibrary's root types do not hold it; or null. */
    private static FType nn32Type() {
        try {
            return FNN32.ZERO.type();
        }
        catch (RuntimeException ex) {
            return null;
        }
    }

    /** The numeral's own type, NaturalNumeral or RadixPointNumeral, or null where the library has none. */
    public static FType numeralType(FValue v) {
        // The static numerals: a numeral's type exists only at compile time, so
        // no value has it when the program runs.
        return null;
    }

    /** v is a numeral whose own type fits t as it is. */
    public static boolean fitsAsIs(FType t, FValue v) {
        FType nt = numeralType(v);
        return nt != null && !(t instanceof BottomType) && nt.subtypeOf(t);
    }

    /** The library's NaturalNumeral or RadixPointNumeral object of the numeral v, one for its site. */
    public static FValue object(FValue v) {
        Site s = ((Numeral) v).site();
        synchronized (s) {
            if (s.object == null) {
                List<FValue> args = new ArrayList<FValue>(4);
                args.add(FInt.make(s.digits));
                if (s.radixPoint) args.add(FInt.make(s.fractionDigits));
                args.add(FInt.make(s.radix));
                args.add(FBigNum.make(s.digitValue));
                Fcn c = (Fcn) library().getRootValue(s.radixPoint ? "RadixPointNumeral" : "NaturalNumeral");
                s.object = c.applyToArgs(args);
            }
            return s.object;
        }
    }

    /**
     * Whether the numeral v is inside the range of target, where target is
     * one of the library's integer types; true for every other type.
     */
    static boolean inRange(FType target, FValue v) {
        Site s = ((Numeral) v).site();
        String n = target.getName();
        BigInteger lo, hi;
        if (n.equals("ZZ32")) { lo = INT_MIN; hi = INT_MAX; }
        else if (n.equals("ZZ64")) { lo = LONG_MIN; hi = LONG_MAX; }
        else if (n.equals("NN32")) { lo = BigInteger.ZERO; hi = NN32_MAX; }
        else if (n.equals("NN64")) { lo = BigInteger.ZERO; hi = NN64_MAX; }
        else return true;
        if (target != (n.equals("NN32") ? nn32Type() : libraryType(n))) return true;
        BigInteger value = s.radixPoint ? s.digitValue : s.signed;
        return value.compareTo(lo) >= 0 && value.compareTo(hi) <= 0;
    }

    /** The numeral v converted to target by its coercion c, one value for its site at each type. */
    static FValue converted(FValue v, FType target, SingleFcn c) {
        Site s = ((Numeral) v).site();
        synchronized (s) {
            FValue r = s.converted.get(target);
            if (r == null) {
                r = convert(target, s, c);
                s.converted.put(target, r);
            }
            return r;
        }
    }

    private static final java.util.Set<String> NUMBER_TYPES = new java.util.HashSet<String>(java.util.Arrays.asList(
        "ZZ32", "ZZ64", "NN32", "NN64", "ZZ", "QQ", "RR64", "RR32"));

    /** Whether t is one of the library's eight number types, whose names no program may declare. */
    public static boolean isLibraryNumber(FType t) {
        return NUMBER_TYPES.contains(t.getName());
    }

    /** Whether v is the value of a folded static expression, not a numeral as written. */
    public static boolean isStaticExpression(FValue v) {
        return v instanceof Numeral && ((Numeral) v).site().kind == NumeralNumbers.Kind.STATIC;
    }

}

/**
 * The coercion to target that is generic over the numeral v's four
 * numbers, where its where clause holds at them; or null. For a negative
 * constant at a program's own type, also null where the type's prefix
 * minus does not apply to the coercion's result. The conversion runs here,
 * once for the site and the type, so that a refusal is known.
 */
static SingleFcn numeralCoercion(FType target, FValue v) {
    Site s = ((Numeral) v).site();
    for (FGenericFunction g : Coercions.numeralCoercions(target, s.radixPoint)) {
        if (!whereHolds(g.getFnDecl(), numbers(g.getFnDecl(), s))) continue;
        synchronized (s) {
            if (!s.converted.containsKey(target)) {
                FValue r = convert(target, s, g);
                if (r == null) return null;
                s.converted.put(target, r);
            }
        }
        return g;
    }
    return null;
}

/**
 * The four numbers by the names the coercion's parameter type gives them:
 * NaturalNumeral[\n, r, v\] or RadixPointNumeral[\n, m, r, v\]. A numeral
 * has no sign: v is the numeral's digits read as one integer.
 */
private static Map<String, BigInteger> numbers(FnDecl fd, Site s) {
    Map<String, BigInteger> m = new HashMap<String, BigInteger>();
    Type pt = (Type) fd.getHeader().getParams().get(0).getIdType().unwrap();
    List<StaticArg> args = ((TraitType) pt).getArgs();
    BigInteger last = s.digitValue;
    BigInteger[] ns = s.radixPoint
        ? new BigInteger[] { BigInteger.valueOf(s.digits), BigInteger.valueOf(s.fractionDigits), BigInteger.valueOf(s.radix), last }
        : new BigInteger[] { BigInteger.valueOf(s.digits), BigInteger.valueOf(s.radix), last };
    for (int i = 0; i < args.size() && i < ns.length; i++) {
        StaticArg a = args.get(i);
        if (a instanceof IntArg && ((IntArg) a).getIntVal() instanceof IntRef)
            m.put(((IntRef) ((IntArg) a).getIntVal()).getName().getText(), ns[i]);
    }
    return m;
}

private static BigInteger evalSize(IntExpr e, Map<String, BigInteger> vals) {
    if (e instanceof IntBase) return ((IntBase) e).getIntVal().getIntVal();
    if (e instanceof IntRef) return vals.get(((IntRef) e).getName().getText());
    if (e instanceof IntBinaryOp) {
        IntBinaryOp b = (IntBinaryOp) e;
        BigInteger l = evalSize(b.getLeft(), vals), r = evalSize(b.getRight(), vals);
        if (l == null || r == null) return null;
        String op = b.getOp().getText();
        if (op.equals("+")) return l.add(r);
        if (op.equals("-")) return l.subtract(r);
        if (op.equals("^")) return l.pow(r.intValue());
        return l.multiply(r);
    }
    return null;
}

/** Whether each comparison of sizes in the coercion's where clause holds at the four numbers. */
private static boolean whereHolds(FnDecl fd, Map<String, BigInteger> vals) {
    Option<WhereClause> w = fd.getHeader().getWhereClause();
    if (w.isNone()) return true;
    for (WhereConstraint c : w.unwrap().getConstraints()) {
        if (!(c instanceof IntConstraint)) continue;
        IntConstraint ic = (IntConstraint) c;
        BigInteger l = evalSize(ic.getLeft(), vals), r = evalSize(ic.getRight(), vals);
        if (l == null || r == null) continue;
        int k = l.compareTo(r);
        String op = ic.getOp().getText();
        boolean ok = op.equals("<") ? k < 0 : op.equals("<=") ? k <= 0 : op.equals(">") ? k > 0
                   : op.equals(">=") ? k >= 0 : op.equals("=") ? k == 0 : true;
        if (!ok) return false;
    }
    return true;
}

/**
 * The coercion's body, run once with the four numbers bound as exact
 * integers, ZZ values, and the coercion's type's own static parameters
 * bound to target's; its parameter is bound to no numeral value, since
 * none exists. For a negative constant at a program's own type, the
 * type's own prefix minus on the result; null where it does not apply.
 */
private static FValue convert(FType target, Site s, SingleFcn c) {
    FGenericFunction g = (FGenericFunction) c;
    FnDecl fd = g.getFnDecl();
    boolean library = isLibraryNumber(target);
    // A folded constant at a library type, a negative constant among them,
    // converts from its exact value (P-173): only a numeral as written
    // reaches a numeral coercion. At a program's type a negative constant
    // is the type's own minus on the coercion of its magnitude (P-174).
    if (library && s.kind != NumeralNumbers.Kind.WRITTEN) return exactAt(target, s);
    boolean minusAfter = s.kind == NumeralNumbers.Kind.NEGATED;
    Map<String, BigInteger> vals = numbers(fd, s);
    Environment clenv = g.getEnv().extendAt(fd);
    List<StaticParam> sps = fd.getHeader().getStaticParams();
    if (target instanceof GenericTypeInstance) {
        List<FType> targs = ((GenericTypeInstance) target).getTypeParams();
        for (int i = 0; i < targs.size() && i < sps.size(); i++) clenv.putType(NodeUtil.getName(sps.get(i)), targs.get(i));
    }
    for (Map.Entry<String, BigInteger> e : vals.entrySet()) clenv.putValue(e.getKey(), FBigNum.make(e.getValue()));
    clenv.bless();
    Environment penv = clenv.extendAt(fd);
    penv.putValue(NodeUtil.nameString(fd.getHeader().getParams().get(0).getName()), FVoid.V);
    penv.bless();
    FValue r = new Evaluator(penv).eval(fd.getBody().unwrap());
    if (minusAfter) {
        Environment within = target.getWithin();
        // walk keys a prefix operator by its fixity (OprUtil.fixityDecorator)
        FValue minus = within == null ? null : within.getTopLevel().getRootValueNull("prefix -");
        if (minus == null && within != null) minus = within.getTopLevel().getRootValueNull("-");
        if (!(minus instanceof Fcn)) return null;
        try {
            r = ((Fcn) minus).applyToArgs(r);
        } catch (FortressException ex) {
            return null;
        }
        if (!target.typeMatch(r)) return null;
    }
    return r;
}

/**
 * A folded constant's exact value at one of the library's number types:
 * exactly into an integer type or QQ, by one rounding into RR64 or RR32,
 * a negated zero IEEE's negative zero; null for a value the type cannot
 * hold exactly, a fraction at an integer type, which the range check and
 * the coercions' kinds already exclude.
 */
private static FValue exactAt(FType target, Site s) {
    BigInteger num = s.signed;
    BigInteger den = BigInteger.valueOf(s.denomBase).pow(s.denomPower);
    String n = target.getName();
    if (n.equals("RR64") || n.equals("RR32")) {
        // the magnitude rounded once, then negated, as rounding to nearest is
        // symmetric; a negated zero is IEEE's negative zero
        BigInteger mag = num.abs();
        boolean neg = num.signum() < 0 || (s.kind == NumeralNumbers.Kind.NEGATED && num.signum() == 0);
        if (n.equals("RR64")) {
            double d = simpleDoubleArith.numeralToDouble(mag, s.denomBase, s.denomPower);
            return FFloat.make(neg ? -d : d);
        }
        float f = simpleDoubleArith.numeralToFloat(mag, s.denomBase, s.denomPower);
        return FRR32.make(neg ? -f : f);
    }
    if (n.equals("QQ")) {
        BigInteger g = num.gcd(den);
        if (g.signum() == 0) g = BigInteger.ONE;
        FValue ratio = library().getRootValueNull("Ratio");
        if (!(ratio instanceof Fcn)) return null;
        List<FValue> args = new ArrayList<FValue>(2);
        args.add(FBigNum.make(num.divide(g)));
        args.add(FBigNum.make(den.divide(g)));
        return ((Fcn) ratio).applyToArgs(args);
    }
    if (!den.equals(BigInteger.ONE)) return null;
    if (n.equals("ZZ32")) return FInt.make(num.intValue());
    if (n.equals("ZZ64")) return FLong.make(num.longValue());
    if (n.equals("NN32")) return FNN32.make(num.intValue());
    if (n.equals("NN64")) return FNN64.make(num.longValue());
    if (n.equals("ZZ")) return FBigNum.make(num);
    return null;
}

/**
 * The value a function declared with the return type range answers, where
 * its body's value is v: a numeral converted where range fixes a type, as
 * a binding converts it, and refused there where it does not convert;
 * without a declared return type, its default.
 */
public static FValue atReturn(FType range, FValue v) {
    if (!hasNumeral(v)) return v;
    if (range != null && !range.typeMatch(v)) {
        FValue c = Coercions.coerce(range, v);
        if (c == null) {
            return error(errorMsg("Type mismatch returning ", v, " (type ", v.type(), ") at the declared return type ", range));
        }
        return c;
    }
    return plain(v);
}

/**
 * The arguments a generic call infers its static arguments from: each
 * numeral at its default, which walk's promotion joins into the
 * narrowest type into which every argument coerces (P-74).  Where the
 * numerals at the positions of one type parameter include one with a
 * radix point, the narrowest default holding them all is an RR64, into
 * which an integer numeral beyond ZZ32 converts exactly though its
 * default does not coerce: such a numeral is read as a ZZ32 stand-in,
 * which promotes with an RR64 to RR64.  The call itself receives the
 * numerals, which convert at the instance's parameters.
 */
public static List<FValue> forInference(List<FValue> args, GenericFunctionOrMethod g) {
    if (!anyNumeral(args)) return args;
    List<FValue> res = plain(args);
    List<Param> params;
    List<StaticParam> sps;
    try {
        params = g.getParams();
        sps = g.getStaticParams();
    }
    catch (RuntimeException ex) {
        return res;
    }
    if (params == null || sps == null || params.size() != args.size()) return res;
    Map<String, List<Integer>> byParam = new HashMap<String, List<Integer>>();
    for (int j = 0; j < params.size(); j++) {
        if (!(args.get(j) instanceof Numeral)) continue;
        Option<TypeOrPattern> ot = params.get(j).getIdType();
        if (ot.isNone() || !(ot.unwrap() instanceof VarType)) continue;
        String n = NodeUtil.nameString(((VarType) ot.unwrap()).getName());
        boolean isStatic = false;
        for (StaticParam sp : sps) if (NodeUtil.getName(sp).equals(n)) isStatic = true;
        if (!isStatic) continue;
        List<Integer> l = byParam.get(n);
        if (l == null) byParam.put(n, l = new ArrayList<Integer>());
        l.add(j);
    }
    for (List<Integer> group : byParam.values()) {
        if (group.size() < 2) continue;
        boolean point = false;
        for (int j : group) if (((Numeral) args.get(j)).site().radixPoint) point = true;
        if (!point) continue;
        for (int j : group) {
            Site s = ((Numeral) args.get(j)).site();
            if (!s.radixPoint && !(s.plain instanceof FInt)) res.set(j, FInt.make(0));
        }
    }
    return res;
}

/** Whether o is the library's NaturalNumeral or RadixPointNumeral object. */
static boolean isNumeralObject(FValue o) {
    if (!(o instanceof FObject)) return false;
    FType t = o.type();
    String n = t.getName();
    if (!n.equals("NaturalNumeral") && !n.equals("RadixPointNumeral")) return false;
    return t == libraryType(n);
}

/** The value of the field name of o, which a getter of the same name may hide from select. */
private static FValue fieldValue(FObject o, String name) {
    FValue f = null;
    try {
        f = o.selectField(name);
    }
    catch (RuntimeException ex) {
        f = null;
    }
    return f != null ? f : o.select(name);
}

private static BigInteger field(FObject o, String name) {
    return fieldValue(o, name).getBigInteger();
}

private static int intField(FObject o, String name) {
    return fieldValue(o, name).getInt();
}

/**
 * Two numeral objects are strictly equivalent when their values are
 * equal: digitValue / radix^fractionDigits, reduced.
 */
static boolean sameValue(FObject a, FObject b) {
    BigInteger va = field(a, "digitValue"), vb = field(b, "digitValue");
    BigInteger da = BigInteger.valueOf(intField(a, "radix")).pow(fractionDigits(a));
    BigInteger db = BigInteger.valueOf(intField(b, "radix")).pow(fractionDigits(b));
    return va.multiply(db).equals(vb.multiply(da));
}

private static int fractionDigits(FObject o) {
    return o.type().getName().equals("RadixPointNumeral") ? intField(o, "fractionDigits") : 0;
}

/**
 * The dispatch caches' key of an argument list: each argument's type, and
 * for a numeral the bottom type, its default's type, its own type and its
 * range, so that a numeral and a value of its default type have different
 * keys, and so do two numerals of one default that an unsigned type of
 * its width holds and does not.
 */
public static final class Keys implements EquivalenceClass<List<FValue>, List<FType>> {
    public int compare(List<FValue> x, List<FType> y) {
        int k = 0;
        int ly = y.size();
        for (FValue v : x) {
            if (v instanceof Numeral) {
                int c = cmp(BottomType.ONLY, y, k++, ly);
                if (c != 0) return c;
                c = cmp(v.type(), y, k++, ly);
                if (c != 0) return c;
                c = cmp(numeralKey(v), y, k++, ly);
                if (c != 0) return c;
                c = cmp(rangeKey(v), y, k++, ly);
                if (c != 0) return c;

520 Coercions.java
 */
public final class Coercions {

    private Coercions() {
    }

    /**
     * The lifted coercions to target, or null when target declares none.
     */
    private static Fcn liftedCoercions(FType target) {
        if (!(target instanceof FTraitOrObject)) return null;
        Environment e = target.getWithin();
        if (e == null) return null;
        FValue f = e.getTopLevel().getRootValueNull(NamingCzar.LIFTED_COERCION_PREFIX + target.getName());
        return f instanceof Fcn ? (Fcn) f : null;
    }

    /**
     * The coercion to target that applies to v without a coercion (coercions
     * do not chain), or null.  A generic target's coercions are instantiated
     * with the target's own static arguments first.
     */
    static SingleFcn coercionFor(FType target, FValue v) {
        // Only a numeral as written reaches a program's coercion from the
        // numeral types: a folded static expression reaches it as its default.
        if (Numerals.isStaticExpression(v) && !Numerals.isLibraryNumber(target)) v = Numerals.plain(v);
        if (Numerals.isNumeral(v)) return numeralCoercionFor(target, v);
        if (target instanceof GenericTypeInstance) {
            SingleFcn g = genericCoercionFor((GenericTypeInstance) target, v);
            if (g != null) return g;
        }
        Fcn lifted = liftedCoercions(target);
        if (lifted == null) return null;
        List<FValue> args = Collections.singletonList(v);
        if (lifted instanceof OverloadedFunction) {
            return ((OverloadedFunction) lifted).bestMatchWithoutCoercion(args);
        }
        SingleFcn f;
        if (lifted instanceof GenericFunctionOrMethod) {
            GenericFunctionOrMethod g = (GenericFunctionOrMethod) lifted;
            try {
                f = EvaluatorBase.inferByUnification(args, g, g.getWithin());
            }
            catch (FortressException ex) {
                return null;
            }
        } else if (lifted instanceof SingleFcn) {
            f = (SingleFcn) lifted;
        } else {
            return null;
        }
        List<FValue> fargs = f.fixupArgCount(args);
        return fargs != null && OverloadedFunction.argsMatchTypes(fargs, f.getDomain()) ? f : null;
    }

    /**
     * The coercion to target from the numeral v's own type, NaturalNumeral or
     * RadixPointNumeral: the one of target's coercions whose parameter type
     * is the narrowest that holds the numeral type, which it receives as the
     * numeral object; or null, also where v is outside target's range when
     * target is an integer type.  A numeral does not reach target through a
     * coercion from its default, since coercions do not chain.
     */
    private static SingleFcn numeralCoercionFor(FType target, FValue v) {
        if (!Numerals.inRange(target, v)) return null;
        return Numerals.numeralCoercion(target, v);
    }

    /**
     * The target's lifted coercions whose one parameter has the numeral type
     * of the kind given, generic over the numeral's four numbers.
     */
    static List<FGenericFunction> numeralCoercions(FType target, boolean radixPoint) {
        List<FGenericFunction> res = new ArrayList<FGenericFunction>();
        Fcn lifted = null;
        if (target instanceof GenericTypeInstance) {
            FTypeGeneric generic = ((GenericTypeInstance) target).getGeneric();
            String name = NamingCzar.LIFTED_COERCION_PREFIX + generic.getName();
            for (Environment e : new Environment[] {((FType) target).getWithin(), generic.getWithin()}) {
                if (e == null) continue;
                FValue f = e.getTopLevel().getRootValueNull(name);
                if (f instanceof Fcn) { lifted = (Fcn) f; break; }
            }
        } else {
            lifted = liftedCoercions(target);
        }
        List<SingleFcn> fs = new ArrayList<SingleFcn>();
        if (lifted instanceof OverloadedFunction) {
            for (Overload o : ((OverloadedFunction) lifted).getOverloads()) fs.add(o.getFn());
        } else if (lifted instanceof SingleFcn) {
            fs.add((SingleFcn) lifted);
        }
        for (SingleFcn f : fs) {
            if (!(f instanceof FGenericFunction)) continue;
            FnDecl fd = ((FGenericFunction) f).getFnDecl();
            if (fd.getHeader().getParams().size() != 1 || fd.getBody().isNone()) continue;
            Option<TypeOrPattern> pt = fd.getHeader().getParams().get(0).getIdType();
            if (pt.isNone() || !(pt.unwrap() instanceof TraitType)) continue;
            String n = ((TraitType) pt.unwrap()).getName().getText();
            if (n.equals(radixPoint ? "RadixPointNumeral" : "NaturalNumeral")) res.add((FGenericFunction) f);
        }
        return res;
    }

    /**
     * The generic target's lifted coercions, each instantiated with the
     * target's static arguments.
     */
    private static List<SingleFcn> instantiatedCoercions(GenericTypeInstance target) {
        List<SingleFcn> res = new ArrayList<SingleFcn>();
        FTypeGeneric generic = target.getGeneric();
        String name = NamingCzar.LIFTED_COERCION_PREFIX + generic.getName();
        Fcn lifted = null;
        for (Environment e : new Environment[] {((FType) target).getWithin(), generic.getWithin()}) {
            if (e == null) continue;
            FValue f = e.getTopLevel().getRootValueNull(name);
            if (f instanceof Fcn) {
                lifted = (Fcn) f;
                break;
            }
        }
        if (lifted == null) return res;
        List<GenericFunctionOrMethod> generics = new ArrayList<GenericFunctionOrMethod>();
        if (lifted instanceof OverloadedFunction) {
            for (Overload o : ((OverloadedFunction) lifted).getOverloads()) {
                if (o.getFn() instanceof GenericFunctionOrMethod) generics.add((GenericFunctionOrMethod) o.getFn());
            }
        } else if (lifted instanceof GenericFunctionOrMethod) {
            generics.add((GenericFunctionOrMethod) lifted);
        }
        List<FType> targs = target.getTypeParams();
        for (GenericFunctionOrMethod g : generics) {
            if (g.getStaticParams().size() != targs.size()) continue;
            try {
                res.add(g.typeApply(targs));
            }
            catch (FortressException ex) {
                // not an instance at these static arguments
            }
        }
        return res;
    }

    /**
     * The most specific of the generic target's lifted coercions, each
     * instantiated with the target's static arguments, that applies to v
     * without a coercion; or null.
     */
    private static SingleFcn genericCoercionFor(GenericTypeInstance target, FValue v) {
        List<FValue> args = Collections.singletonList(v);
        SingleFcn best = null;
        for (SingleFcn f : instantiatedCoercions(target)) {
            List<FValue> fargs = f.fixupArgCount(args);
            if (fargs == null || !OverloadedFunction.argsMatchTypes(fargs, f.getDomain())) continue;
            if (best == null || FTypeTuple.moreSpecificThan(f.getDomain(), best.getDomain())) best = f;
        }
        return best;
    }

    /**
     * t admits v: v is a t, or converts to t by one coercion (a tuple element
     * by element).
     */
    public static boolean admits(FType t, FValue v) {
        if (t.typeMatch(v) || Numerals.fitsAsIs(t, v)) return true;
        if (t instanceof FTypeTuple) {
            if (!(v instanceof FTuple)) return false;
            List<FType> types = ((FTypeTuple) t).getTypes();
            List<FValue> vals = ((FTuple) v).getVals();
            if (types.size() != vals.size()) return false;
            for (int j = 0; j < types.size(); j++) {
                if (types.get(j) instanceof FTypeRest) return false;
                if (!admits(types.get(j), vals.get(j))) return false;
            }
            return true;
        }
        return coercionFor(t, v) != null;
    }

    /**
     * A value of type c converts to d: d declares a coercion from a supertype
     * of c.
     */
    public static boolean convertsInto(FType c, FType d) {
        for (FType a : coercionSources(d)) {
            if (c.subtypeOf(a)) return true;
        }
        return false;
    }

    private static final Map<Environment, List<FType>> coercionTypesByEnv =
            new IdentityHashMap<Environment, List<FType>>();

    public static synchronized void reset() {
        coercionTypesByEnv.clear();
    }

    /**
     * The non-generic trait and object types named at the top level of e that
     * declare a coercion.
     */
    private static synchronized List<FType> coercionTypes(Environment e) {
        List<FType> l = coercionTypesByEnv.get(e);
        if (l != null) return l;
        l = new ArrayList<FType>();
        Set<String> seen = new HashSet<String>();
        for (String s : e.youngestFrame()) {
            if (!s.startsWith(NamingCzar.LIFTED_COERCION_PREFIX) || !seen.add(s)) continue;
            FType t;
            try {
                t = e.getTypeNull(s.substring(NamingCzar.LIFTED_COERCION_PREFIX.length()));
            }
            catch (FortressException ex) {
                t = null;
            }
            if (t instanceof FTraitOrObject && !(t instanceof FTypeGeneric)) l.add(t);
        }
        coercionTypesByEnv.put(e, l);
        return l;
    }

    /**
     * The types v converts to by one coercion and is not already of: the
     * coercions declared at the top level of the library, of within, and of
     * the component of v's type.
     */
    public static List<FType> coercionTargets(FValue v, Environment within) {
        Set<Environment> envs = new LinkedHashSet<Environment>();
        Environment library = null;
        try {
            library = Driver.getFortressLibrary();
        }
        catch (RuntimeException ex) {
            library = null;
        }
        if (library != null) envs.add(library.getTopLevel());
        if (within != null) envs.add(within.getTopLevel());
        FType vt = v.type();
        if (vt instanceof FTraitOrObjectOrGeneric && vt.getWithin() != null) envs.add(vt.getWithin().getTopLevel());
        List<FType> targets = new ArrayList<FType>();
        for (Environment e : envs) {
            for (FType t : coercionTypes(e)) {
                if (!targets.contains(t) && !t.typeMatch(v) && coercionFor(t, v) != null) targets.add(t);
            }
        }
        return targets;
    }

    /**
     * v converted by the coercion c to target.
     */
    static FValue apply(SingleFcn c, FType target, FValue v) {
        FValue r = Numerals.isNumeral(v) && c instanceof FGenericFunction && !(Numerals.isStaticExpression(v) && !Numerals.isLibraryNumber(target))
                   ? Numerals.converted(v, target, c)
                   : c.applyInnerPossiblyGeneric(Collections.singletonList(Numerals.plain(v)));
        if (!target.typeMatch(r)) {
            return error(errorMsg("Coercion ", c, " to ", target, " returned ", r, " of type ", r.type()));
        }
        return r;
    }

    /**
     * v converted to target by one of target's coercions, or null when none
     * applies to v.  A tuple converts element by element.
     */
    public static FValue coerce(FType target, FValue v) {
        if (target instanceof FTypeTuple) return coerceTuple((FTypeTuple) target, v);
        SingleFcn c = coercionFor(target, v);
        return c == null ? null : apply(c, target, v);
    }

    /**
     * The tuple v with each element that is not of its element type of target
     * converted to it; or null when v is not a tuple of target's size, when
     * target has a varargs element, or when an element does not convert.
     */
    private static FValue coerceTuple(FTypeTuple target, FValue v) {
        if (!(v instanceof FTuple)) return null;
        List<FType> types = target.getTypes();
        List<FValue> vals = ((FTuple) v).getVals();
        if (types.size() != vals.size()) return null;
        List<FValue> converted = new ArrayList<FValue>(vals.size());
        for (int j = 0; j < types.size(); j++) {
            FType t = types.get(j);
            if (t instanceof FTypeRest) return null;
            FValue e = vals.get(j);
            if (!t.typeMatch(e)) {
                e = coerce(t, e);
                if (e == null) return null;
            }
            converted.add(e);
        }
        return FTuple.make(converted);
    }

    /**
     * The value of a variable declared with type t in e, converted when it is
     * not a t and a coercion to t applies.  Anything that goes wrong before a
     * coercion is found leaves the value as it is, for the declaration's own
     * check to report.
     */
    public static FValue coerceToDeclared(Type t, Environment e, FValue v) {
        FType ft;
        try {
            ft = new EvalType(e).evalType(t);
            if (ft.typeMatch(v)) return v;
        }
        catch (FortressException ex) {
            return v;
        }
        FValue c = coerce(ft, v);
        return c == null ? v : c;
    }

    /**
     * The types a coercion to u is declared from.
     */
    private static List<FType> coercionSources(FType u) {
        Fcn lifted = liftedCoercions(u);
        List<FType> sources = new ArrayList<FType>();
        if (lifted instanceof OverloadedFunction) {
            for (Overload o : ((OverloadedFunction) lifted).getOverloads()) {
                addSource(o.getFn(), sources);
            }
        } else if (lifted instanceof SingleFcn) {
            addSource((SingleFcn) lifted, sources);
        }
        return sources;
    }

    private static void addSource(SingleFcn f, List<FType> sources) {
        if (f instanceof GenericFunctionOrMethod) return;
        List<FType> d = f.getDomain();
        if (d.size() == 1) sources.add(d.get(0));
    }

    /**
     * t is no less specific than u: t is a subtype of u, or t excludes, can be
     * coerced to, and rejects u.
     */
    private static boolean noLessSpecific(FType t, FType u) {
        if (t.subtypeOf(u)) return true;
        if (!t.excludesOther(u)) return false;
        boolean coercesTo = false;
        for (FType a : coercionSources(u)) {
            if (t.subtypeOf(a)) coercesTo = true;
        }
        if (!coercesTo) return false;
        for (FType a : coercionSources(t)) {
            if (!a.excludesOther(u)) return false;
        }
        return true;
    }

    /**
     * The domain c is more specific than the domain d over the first n
     * parameter positions, element by element.
     */
    static boolean moreSpecific(List<FType> c, List<FType> d, int n) {
        boolean differ = false;
        for (int j = 0; j < n; j++) {
            FType t = Useful.clampedGet(c, j).deRest();
            FType u = Useful.clampedGet(d, j).deRest();
            if (!noLessSpecific(t, u)) return false;
            if (t != u) differ = true;
        }
        return differ;
    }

    /**
     * target itself, or, where some argument is a numeral at a parameter that
     * its own numeral type fits and its default does not, a call that makes
     * each such numeral its numeral object and dispatches the arguments again,
     * so that a functional method of the numeral type is found on that object.
     */
    static SingleFcn withNumeralObjects(SingleFcn target, List<FValue> args, OverloadedFunction owner) {
        if (target instanceof CoercedCall) return target;   // its converted arguments are dispatched again
        List<FValue> oargs = target.fixupArgCount(args);
        if (oargs == null) return target;
        List<FType> domain = target.getDomain();
        boolean[] objects = new boolean[oargs.size()];
        boolean any = false;
        for (int j = 0; j < oargs.size(); j++) {
            FType t = Useful.clampedGet(domain, j).deRest();
            FValue a = oargs.get(j);
            if (Numerals.isNumeral(a) && !t.typeMatch(a) && Numerals.fitsAsIs(t, a)) {
                objects[j] = true;
                any = true;
            }
        }
        return any ? new CoercedCall(target, new SingleFcn[oargs.size()], owner, objects) : target;
    }

    /**
     * The coercions for each argument position of an overloaded call, chosen
     * by the argument types and kept in the per-argument-type cache: for each
     * position the coercion that converts it, or null, together with the
     * overload that makes them applicable.  The converted arguments are
     * dispatched as an ordinary call.
     */
    static final class CoercedCall extends SingleFcn {
        private final SingleFcn target;
        private final SingleFcn[] coercions;
        private final OverloadedFunction owner;
        private final boolean[] objects;   // the positions of numerals that become their numeral objects, or null

        CoercedCall(SingleFcn target, SingleFcn[] coercions, OverloadedFunction owner) {
            this(target, coercions, owner, null);
        }

        CoercedCall(SingleFcn target, SingleFcn[] coercions, OverloadedFunction owner, boolean[] objects) {
            super(target.getWithin());
            this.target = target;
            this.coercions = coercions;
            this.owner = owner;
            this.objects = objects;
        }

        int arity() {
            return coercions.length;
        }

        List<FValue> convert(List<FValue> args) {
            List<FValue> oargs = target.fixupArgCount(args);
            List<FValue> res = new ArrayList<FValue>(oargs);
            List<FType> domain = target.getDomain();
            for (int j = 0; j < coercions.length; j++) {
                if (objects != null && objects[j]) {
                    res.set(j, Numerals.object(oargs.get(j)));
                } else if (coercions[j] != null) {
                    res.set(j, apply(coercions[j], Useful.clampedGet(domain, j).deRest(), oargs.get(j)));
                }
            }
            return res;
        }

        @Override
        public FValue applyInnerPossiblyGeneric(List<FValue> args) {
            return owner.applyInnerPossiblyGeneric(convert(args));
        }

        @Override
        public String at() {
            return target.at();
        }

        public String stringName() {
            return target.stringName();
        }

        @Override
        public List<FType> getDomain() {
            return target.getDomain();
        }

        @Override
        public FType getRange() {
            return target.getRange();
        }

        @Override
        public IdOrOpOrAnonymousName getFnName() {
            return target.getFnName();
        }

        @Override
        public FType type() {
            return target.type();
        }

        @Override
        public boolean seqv(FValue other) {
            return this == other;
        }

        @Override
        public String toString() {
            return "coerced " + target;
        }
    }
}

